changeSet.sql:
ALTER TABLE lib_pages ADD COLUMN printed_page TEXT NULL;
ALTER TABLE lib_pages ADD COLUMN part TEXT NULL;
ALTER TABLE lib_pages ADD COLUMN pdf_page_number INTEGER NULL;
CREATE INDEX idx_lib_pages_part ON lib_pages(book_id, part);

rollback.sql:
DROP INDEX IF EXISTS idx_lib_pages_part;
ALTER TABLE lib_pages DROP COLUMN pdf_page_number;
ALTER TABLE lib_pages DROP COLUMN part;
ALTER TABLE lib_pages DROP COLUMN printed_page;
